import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [problems, setProblems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProblems();
  }, []);

  const fetchProblems = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProblems(response.data.problems || []);
    } catch (error) {
      console.error('Error fetching problems:', error);
    } finally {
      setLoading(false);
    }
  };

  // Stats
  const stats = [
    { label: 'Total Problems', value: problems.length, icon: '📚', color: '#6C63FF' },
    { label: 'Solved', value: user?.stats?.problemsSolved || 0, icon: '✅', color: '#4CAF50' },
    { label: 'Attempts', value: user?.stats?.totalAttempts || 0, icon: '📝', color: '#FF9800' },
    { label: 'Success Rate', value: user?.stats?.totalAttempts > 0 
        ? Math.round((user.stats.problemsSolved / user.stats.totalAttempts) * 100) 
        : 0, icon: '🏆', color: '#E91E63', suffix: '%' },
  ];

  return (
    <div style={styles.container}>
      {/* Main Content */}
      <div style={styles.mainContent}>
        {/* Top Bar */}
        <div style={styles.topBar}>
          <div>
            <h1 style={styles.pageTitle}>Dashboard</h1>
          </div>
          <div style={styles.topBarActions}>
            <button style={styles.refreshBtn} onClick={() => window.location.reload()}>
              🔄 REFRESH
            </button>
            <div style={styles.weather}>
              <span>☀️</span> 29°
            </div>
          </div>
        </div>

        {/* Stats Cards */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statLeft}>
                <span style={styles.statIcon}>{stat.icon}</span>
                <div>
                  <div style={styles.statValue}>{stat.value}{stat.suffix || ''}</div>
                  <div style={styles.statLabel}>{stat.label}</div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Problem Cards - Like TOOFAAN */}
        <div style={styles.problemsSection}>
          <h2 style={styles.sectionTitle}>📋 Assignments</h2>
          
          <div style={styles.problemGrid}>
            {loading ? (
              <div style={styles.loadingText}>Loading...</div>
            ) : problems.length === 0 ? (
              <div style={styles.emptyState}>No assignments available</div>
            ) : (
              problems.map((problem, index) => (
                <div key={problem._id} style={styles.problemCard}>
                  {/* Program Number */}
                  <div style={styles.programNumber}>
                    PROGRAM-{index + 1}
                  </div>
                  
                  {/* Problem Title */}
                  <div style={styles.problemTitle}>
                    {problem.title}
                  </div>
                  
                  {/* Problem ID / Lab */}
                  <div style={styles.problemMeta}>
                    <span style={styles.problemId}>FS-A1-Audi-2027</span>
                    <span style={styles.problemLab}>LAB</span>
                  </div>
                  
                  {/* Started Info */}
                  <div style={styles.startedInfo}>
                    <span style={styles.startedLabel}>Started</span>
                    <span style={styles.startedDate}>
                      on Tuesday, {new Date(problem.createdAt).toLocaleDateString('en-US', { 
                        day: 'numeric', 
                        month: 'long', 
                        year: 'numeric' 
                      })}
                    </span>
                  </div>
                  
                  {/* Difficulty Badge */}
                  <div style={styles.difficultyRow}>
                    <span style={{
                      ...styles.difficultyBadge,
                      background: problem.difficulty === 'Easy' ? '#4CAF50' :
                                 problem.difficulty === 'Medium' ? '#FF9800' : '#f44336',
                    }}>
                      {problem.difficulty || 'Easy'}
                    </span>
                  </div>
                  
                  {/* Attempt Button */}
                  <button 
                    style={styles.attemptBtn}
                    onClick={() => navigate(`/problems/${problem._id}`)}
                    onMouseEnter={(e) => e.currentTarget.style.background = '#6C63FF'}
                    onMouseLeave={(e) => e.currentTarget.style.background = '#4A3FCF'}
                  >
                    ATTEMPT →
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    background: '#f0f2f5',
    fontFamily: 'Inter, sans-serif',
  },
  mainContent: {
    padding: '24px 32px',
    maxWidth: '1400px',
    margin: '0 auto',
  },
  topBar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px',
    flexWrap: 'wrap',
    gap: '15px',
  },
  pageTitle: {
    fontSize: '28px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  topBarActions: {
    display: 'flex',
    alignItems: 'center',
    gap: '15px',
  },
  refreshBtn: {
    padding: '8px 20px',
    background: '#6C63FF',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontSize: '12px',
    fontWeight: 600,
    cursor: 'pointer',
    letterSpacing: '0.5px',
  },
  weather: {
    padding: '8px 16px',
    background: 'white',
    borderRadius: '8px',
    fontSize: '14px',
    fontWeight: 500,
    boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
  },
  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '20px',
    marginBottom: '30px',
  },
  statCard: {
    background: 'white',
    padding: '18px 24px',
    borderRadius: '12px',
    boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
  },
  statLeft: {
    display: 'flex',
    alignItems: 'center',
    gap: '14px',
  },
  statIcon: {
    fontSize: '28px',
  },
  statValue: {
    fontSize: '24px',
    fontWeight: 700,
    color: '#1a1a2e',
  },
  statLabel: {
    fontSize: '13px',
    color: '#666',
    marginTop: '2px',
  },
  problemsSection: {
    background: 'white',
    padding: '24px',
    borderRadius: '16px',
    boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
  },
  sectionTitle: {
    fontSize: '20px',
    fontWeight: 600,
    color: '#1a1a2e',
    marginBottom: '20px',
    paddingBottom: '15px',
    borderBottom: '2px solid #f0f2f5',
  },
  problemGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
    gap: '20px',
  },
  problemCard: {
    background: '#f8f9fa',
    borderRadius: '12px',
    padding: '20px',
    border: '1px solid #e9ecef',
    transition: 'all 0.3s',
  },
  programNumber: {
    fontSize: '14px',
    fontWeight: 700,
    color: '#6C63FF',
    marginBottom: '6px',
    letterSpacing: '0.5px',
  },
  problemTitle: {
    fontSize: '18px',
    fontWeight: 600,
    color: '#1a1a2e',
    marginBottom: '8px',
  },
  problemMeta: {
    display: 'flex',
    gap: '12px',
    marginBottom: '12px',
    fontSize: '13px',
  },
  problemId: {
    color: '#666',
    fontWeight: 500,
  },
  problemLab: {
    color: '#6C63FF',
    fontWeight: 600,
    background: 'rgba(108, 99, 255, 0.1)',
    padding: '0 10px',
    borderRadius: '4px',
  },
  startedInfo: {
    display: 'flex',
    flexDirection: 'column',
    marginBottom: '12px',
    padding: '10px 14px',
    background: 'white',
    borderRadius: '8px',
    border: '1px solid #e9ecef',
  },
  startedLabel: {
    fontSize: '11px',
    fontWeight: 600,
    color: '#999',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
  },
  startedDate: {
    fontSize: '14px',
    color: '#333',
    marginTop: '2px',
  },
  difficultyRow: {
    marginBottom: '14px',
